let inp = {}; try { inp = $('Webhook Trigger').first().json.body || {}; } catch (e) { inp = {}; }
const seed = (inp.seed || '').toString().trim();
const jobId = (inp.jobId || '').toString().trim();
const market = (inp.market || 'us').toString().toLowerCase();
const lang = (inp.lang || 'en').toString().toLowerCase();
const category = (inp.category || 'general').toString().trim();

function safe(name) { try { return $('' + name).first().json; } catch (e) { return undefined; } }

// --- 1) Google Suggest 解析 ---
let g = safe('HTTP: Google Suggest') || [];
let gsug = [];
if (Array.isArray(g) && g.length > 1 && Array.isArray(g[1])) gsug = g[1];

// --- 2) DDG Suggest 解析 ---
let dAll = []; try { dAll = $('HTTP: DDG Suggest').all(); } catch (e) {}
let dsug = [];
for (const it of dAll) {
  const arr = Array.isArray(it.json) ? it.json : [];
  for (const o of arr) dsug.push(o.phrase || o);
}

// --- 3) SERP HTML 解析 ---
const serp = safe('HTTP: SERP') || {};
const html = (serp.data || serp.body || serp || '').toString();

// --- 聚合长尾词 ---
let seen = new Set(); let sug = [];
for (const s of [...gsug, ...dsug]) {
  const k = (s || '').toLowerCase().trim();
  if (k && !seen.has(k)) { seen.add(k); sug.push(s); }
}

// --- 4) 竞争难度（来自 SERP 构成）---
let difficulty = 60, brandInTop = 0, topDomains = [], ads = false;
if (html && html.length > 200) {
  const links = (html.match(/https?:\/\/([a-z0-9-]+\.[a-z]{2,})(\/|$)/gi) || [])
    .map(u => u.replace(/^https?:\/\//, '').split('/')[0]);
  const brands = ['wikipedia','youtube','amazon','google','facebook','twitter','reddit','pinterest','spotify','apple','github','linkedin','quora','medium'];
  topDomains = links.slice(0, 10);
  brandInTop = topDomains.filter(d => brands.some(b => d.includes(b))).length;
  ads = /(data-text-ad|adsbygoogle|span class="[^\"]*ad|sponsored|广告|class="[^\"]*commercial)/i.test(html);
  const inner = topDomains.filter(d => !brands.some(b => d.includes(b))).length;
  difficulty = Math.max(10, Math.min(95, Math.round(40 + brandInTop * 8 - inner * 3)));
}

// --- 5) 综合评分（0-100，跨品类可比）---
const volumeProxy = Math.min(100, 20 + sug.length * 2);
const ease = 100 - difficulty;
let cpc = 1.0;
try { const env = (typeof $env !== 'undefined') ? $env : (n8n && n8n.env) || {}; cpc = parseFloat(env.RESEARCH_CPC || (process && process.env && process.env.RESEARCH_CPC) || '1.0') || 1.0; } catch (e) {}
const adBonus = ads ? 15 : 0;
const worth = Math.round(0.35 * volumeProxy + 0.35 * ease + 0.15 * adBonus + 0.15 * 0);

let verdict, advice;
if (worth >= 65 && difficulty <= 60) { verdict = '✅ 值得做'; advice = '建议优先排期，作为核心词/栏目页主攻。'; }
else if (worth >= 45) { verdict = '🟡 可尝试（长尾切入）'; advice = '建议先做长尾子词页面，再逐步攻核心词。'; }
else { verdict = '🔴 暂不优先'; advice = '竞争激烈或商业意图弱，建议换词或细分角度。'; }

const report = [
  '🔍 关键词可行性分析：' + seed,
  '市场: ' + market + ' / 语言: ' + lang + ' / 品类: ' + category,
  '──────────────',
  '衍生长尾词 (' + sug.length + '): ' + (sug.slice(0, 15).join('、') || '（未取到，可能网络受限）'),
  '──────────────',
  '竞争难度(估计): ' + difficulty + ' / 100   ' + (difficulty <= 40 ? '易' : difficulty <= 60 ? '中' : '难'),
  '品牌站占位(前10): ' + brandInTop + ' 个',
  'SERP 广告: ' + (ads ? '有 → 变现路径清晰' : '无 → 偏信息词'),
  '──────────────',
  '综合值得做评分: ' + worth + ' / 100',
  '结论: ' + verdict,
  '建议: ' + advice,
  '──────────────',
  '（CPC 默认 ' + cpc + '；接入会员 API 后可在 env 配 RESEARCH_CPC 或改用本地 Python 引擎拿实时值。本工作流为免费兜底版。）'
].join('\n');

return [{ json: {
  report,
  analysis: {
    seed, suggestions: sug, suggestionCount: sug.length,
    difficulty, brandInTop, topDomains: topDomains.slice(0, 10),
    adsPresent: ads, volumeProxy, worthScore: worth, cpcUsed: cpc,
    verdict, reasons: [advice], monetization: ads ? '广告/联盟' : '信息词-间接'
  }
} }];

const fs = require('fs');
let inp = {}; try { inp = $('Webhook Trigger').first().json.body || {}; } catch (e) { inp = {}; }
const jobId = (inp.jobId || '').toString();
let report = ''; try { report = ($('Code: Analyze').first().json.report) || ''; } catch (e) { report = ''; }
let analysis = {}; try { analysis = ($('Code: Analyze').first().json.analysis) || {}; } catch (e) {}
const payload = {
  jobId: jobId, slug: '', url: '', dns: '',
  status: report ? 'seo-done' : 'seo-partial',
  result: report,
  analysis: analysis,
  log: report ? '关键词调研报告已生成' : '调研流程已触发，但报告内容暂未生成（抓取可能失败）'
};
try {
  const dir = '/home/node/sites/_bridge_cb';
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(dir + '/' + (jobId || 'unknown') + '.json', JSON.stringify(payload, null, 2));
} catch (e) { /* 忽略 */ }
return [{ json: { ok: true, jobId: jobId } }];
